&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de sorci&#232;re&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_sorci&#232;re_0&quot; href=&quot;#Les_arch&#233;types_de_sorci&#232;re_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amie-Des-Animaux-(Sorci&#232;re).html&quot; title=&quot;Amie des animaux&quot;&gt;Amie des animaux&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Buda-(Sorci&#232;re).html&quot; title=&quot;Buda&quot;&gt;Buda&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnoll.html&quot; title=&quot;Gnoll&quot;&gt;Gnoll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Canalisatrice-De-Mal&#233;fices-(Sorci&#232;re).html&quot; title=&quot;Canalisatrice de mal&#233;fices&quot;&gt;Canalisatrice de mal&#233;fices&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;risseuse-Balafr&#233;e-(Sorci&#232;re).html&quot; title=&quot;Gu&#233;risseuse balafr&#233;e&quot;&gt;Gu&#233;risseuse balafr&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchetombe-(Sorci&#232;re).html&quot; title=&quot;Marchetombe&quot;&gt;Marchetombe&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Occultiste-Des-Dimensions-(Sorci&#232;re).html&quot; title=&quot;Occultiste des dimensions&quot;&gt;Occultiste des dimensions&lt;/a&gt; (RSE)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protectrice-Des-Lignes-Telluriques-(Sorci&#232;re).html&quot; title=&quot;Protectrice des lignes telluriques&quot;&gt;Protectrice des lignes telluriques&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Aux-Toxines-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re aux toxines&quot;&gt;Sorci&#232;re aux toxines&lt;/a&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-De-Lhiver-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re de l&amp;#39;hiver&quot;&gt;Sorci&#232;re de l&#39;hiver&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Des-Mers-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re des mers&quot;&gt;Sorci&#232;re des mers&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-De-Village-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re de village&quot;&gt;Sorci&#232;re de village&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Des-Montagnes-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re des montagnes&quot;&gt;Sorci&#232;re des montagnes&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Li&#233;e-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re li&#233;e&quot;&gt;Sorci&#232;re li&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Synergiste-(Sorci&#232;re).html&quot; title=&quot;Synergiste&quot;&gt;Synergiste&lt;/a&gt; (&lt;i&gt;FF&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tisseuse-De-R&#234;ves-(Sorci&#232;re).html&quot; title=&quot;Tisseuse de r&#234;ves&quot;&gt;Tisseuse de r&#234;ves&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Changelin-(Race).html&quot; title=&quot;Les changelins&quot;&gt;Changelin&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;div style=&quot;float:right; padding:2px 2px 6px 6px&quot;&gt;
&lt;img class=&quot;opachover&quot; bopac=&quot;0.4&quot; style=&quot;opacity:0.7; float:left; height:36px; box-shadow:4px 4px 2px #e7dfc6; border-radius:10px; padding:6px; background-color:#f3efe2&quot; src=&quot;/Wiki/images/quill.png&quot; title=&quot;Contenu traduit
par la communaut&#233;. (voir Source)&quot;&gt;
&lt;/div&gt;&lt;div class=&quot;description&quot;&gt;&lt;b&gt;Source :&lt;/b&gt; People of the River (PotR).&lt;/div&gt;&lt;i&gt;Une sorci&#232;re aux toxines se sp&#233;cialise dans les &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt; - cr&#233;ant de dangereuses mixtures entre la science et la magie, et les appliquant aux armes, pi&#232;ges, et m&#234;me &#224; sa magie.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Empoisonneuse (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Empoisonneuse_Ext_0&quot; href=&quot;#Empoisonneuse_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une sorci&#232;re aux toxines peut choisir d&#39;acc&#233;der &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;d&#233;couverte&lt;/a&gt; d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; &#224; la place d&#39;un mal&#233;fice, mal&#233;fice majeur ou grand mal&#233;fice, utilisant son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;sorci&#232;re&lt;/a&gt; comme niveau d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt;. Elle a acc&#232;s aux d&#233;couvertes suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Mal&#233;fices&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#POISONCONCENTRE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;poison concentr&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#TRANSFORMATIONDEPOISON&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;transformation de poison&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#POISONCOLLANT&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;poison collant&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Mal&#233;fices majeurs&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#POISONMALIN&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;poison malin&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#CHAIRECOEURANTE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;chair &#233;coeurante&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Grands mal&#233;fices&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#CONTACTEMPOISONNE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;contact empoisonn&#233;&lt;/a&gt; (grande d&#233;couverte).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Utilisation du poison&lt;a class=&quot;headeranchor&quot; id=&quot;Utilisation_du_poison_1&quot; href=&quot;#Utilisation_du_poison_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, la sorci&#232;re aux toxines apprend &#224; utiliser les &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt; et ne risque pas de s’empoisonner accidentellement quand elle enduit une arme.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Paroles venimeuses (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Paroles_venimeuses_Ext_2&quot; href=&quot;#Paroles_venimeuses_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, lorsqu&#39;une sorci&#232;re aux toxines vise une cible unique avec un &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt;, elle peut impr&#233;gner le mal&#233;fice d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poison&lt;/a&gt; de blessure ou de contact qu&#39;elle tient en main. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du mal&#233;fice et du poison sont r&#233;duits de 2 ; si la cible &#233;choue son jet de r&#233;sistance au mal&#233;fice, elle doit faire un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; contre le DD du poison ou &#234;tre empoisonn&#233;e. Au niveau 10, la p&#233;nalit&#233; au DD du mal&#233;fice et du poison passe &#224; -1, et la sorci&#232;re peut empoisonner ses mal&#233;fices avec des poisons d&#39;ingestion ou d&#39;inhalation &#233;galement. Ce pouvoir remplace les mal&#233;fices de sorci&#232;re de niveau 2 et 10.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mal&#233;fices&lt;a class=&quot;headeranchor&quot; id=&quot;Mal&#233;fices_3&quot; href=&quot;#Mal&#233;fices_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les mal&#233;fices de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type de sorci&#232;re aux toxines : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Chaudron&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;chaudron&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#D&#233;p&#233;rissement&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;d&#233;p&#233;rissement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Tremperdanslepoison&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;tremper dans le poison&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#D&#233;guisement&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;d&#233;guisement&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mal&#233;fices majeurs&lt;a class=&quot;headeranchor&quot; id=&quot;Mal&#233;fices_majeurs_4&quot; href=&quot;#Mal&#233;fices_majeurs_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les mal&#233;fices majeurs de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type de sorci&#232;re aux toxines : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Cuisinerlesgens&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;cuisiner les gens&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Brouetdelasorci&#232;re&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;brouet de la sorci&#232;re&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Grands mal&#233;fices&lt;a class=&quot;headeranchor&quot; id=&quot;Grands_mal&#233;fices_5&quot; href=&quot;#Grands_mal&#233;fices_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les grands mal&#233;fices de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type de sorci&#232;re aux toxines : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Sommeil&#233;ternel&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sommeil &#233;ternel&lt;/a&gt;.
